import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = r"""
#include <torch/extension.h>
#include <c10/util/Optional.h>

torch::Tensor conv2d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

#define TX 16
#define TY 16
#define CO_BLOCK 32
#define C_TILE 16

__global__ __launch_bounds__(TX * TY) void conv2d_direct_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    int N, int C, int H, int W,
    int O, int K, int OH, int OW,
    int stride, int padding, int dilation) {
    extern __shared__ float smem[];
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int ow = blockIdx.x * TX + tx;
    const int oh = blockIdx.y * TY + ty;
    const int co_tiles = (O + CO_BLOCK - 1) / CO_BLOCK;
    const int n = blockIdx.z / co_tiles;
    const int co0 = (blockIdx.z % co_tiles) * CO_BLOCK;
    const int tid = ty * TX + tx;
    const int nthreads = TX * TY;
    const int ckk = K * K;
    // Dimensions of the input tile (with halo) needed by this block's TX x TY output tile.
    const int IH_TILE = (TY - 1) * stride + (K - 1) * dilation + 1;
    const int IW_TILE = (TX - 1) * stride + (K - 1) * dilation + 1;
    const int ih0 = blockIdx.y * TY * stride - padding;
    const int iw0 = blockIdx.x * TX * stride - padding;
    const int sx_count = C_TILE * IH_TILE * IW_TILE;
    const int sw_count = CO_BLOCK * C_TILE * ckk;
    float* sx = smem;              // staged input tile: [C_TILE][IH_TILE][IW_TILE]
    float* sw = smem + sx_count;   // staged weights:    [CO_BLOCK][C_TILE][K*K]
    const bool active = (oh < OH && ow < OW);
    float acc[CO_BLOCK];
#pragma unroll
    for (int i = 0; i < CO_BLOCK; ++i) {
        acc[i] = 0.0f;
    }
    for (int c0 = 0; c0 < C; c0 += C_TILE) {
        const int c_len = min(C_TILE, C - c0);
        // Cooperatively stage the input tile (with halo) into shared memory.
        for (int idx = tid; idx < sx_count; idx += nthreads) {
            const int c = idx / (IH_TILE * IW_TILE);
            const int rem = idx % (IH_TILE * IW_TILE);
            const int ih = rem / IW_TILE;
            const int iw = rem % IW_TILE;
            const int cg = c0 + c;
            const int ihg = ih0 + ih;
            const int iwg = iw0 + iw;
            float val = 0.0f;
            if (cg < C && ihg >= 0 && ihg < H && iwg >= 0 && iwg < W) {
                val = x[((n * C + cg) * H + ihg) * W + iwg];
            }
            sx[idx] = val;
        }
        // Cooperatively stage the weight tile into shared memory.
        for (int idx = tid; idx < sw_count; idx += nthreads) {
            const int i = idx / (C_TILE * ckk);
            const int rem = idx % (C_TILE * ckk);
            const int c = rem / ckk;
            const int kk = rem % ckk;
            const int co = co0 + i;
            const int cg = c0 + c;
            float val = 0.0f;
            if (co < O && cg < C) {
                val = w[(co * C + cg) * ckk + kk];
            }
            sw[idx] = val;
        }
        __syncthreads();
        if (active) {
            const int ih_base = ty * stride;
            const int iw_base = tx * stride;
            for (int c = 0; c < c_len; ++c) {
                const float* sx_c = sx + c * IH_TILE * IW_TILE;
                for (int kh = 0; kh < K; ++kh) {
                    const float* sx_row = sx_c + (ih_base + kh * dilation) * IW_TILE;
                    for (int kw = 0; kw < K; ++kw) {
                        const float xv = sx_row[iw_base + kw * dilation];
                        const int wbase = c * ckk + kh * K + kw;
#pragma unroll
                        for (int i = 0; i < CO_BLOCK; ++i) {
                            acc[i] = fmaf(xv, sw[i * C_TILE * ckk + wbase], acc[i]);
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    if (active) {
#pragma unroll
        for (int i = 0; i < CO_BLOCK; ++i) {
            const int co = co0 + i;
            if (co < O) {
                float out = acc[i];
                if (b != nullptr) {
                    out += b[co];
                }
                y[((n * O + co) * OH + oh) * OW + ow] = out;
            }
        }
    }
}

torch::Tensor conv2d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be OIHW");
    TORCH_CHECK(groups == 1, "only groups=1 is supported");
    TORCH_CHECK(weight.size(2) == weight.size(3), "only square kernels are supported");

    auto xc = x.contiguous();
    auto wc = weight.contiguous();

    torch::Tensor bc;
    const float* bptr = nullptr;
    if (bias.has_value() && bias->defined() && bias->numel() > 0) {
        TORCH_CHECK(bias->is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias->scalar_type() == at::kFloat, "bias must be float32");
        bc = bias->contiguous();
        bptr = bc.data_ptr<float>();
    }

    const int N = static_cast<int>(xc.size(0));
    const int C = static_cast<int>(xc.size(1));
    const int H = static_cast<int>(xc.size(2));
    const int W = static_cast<int>(xc.size(3));
    const int O = static_cast<int>(wc.size(0));
    const int K = static_cast<int>(wc.size(2));

    TORCH_CHECK(static_cast<int>(wc.size(1)) == C, "weight/input channel mismatch");
    if (bptr != nullptr) {
        TORCH_CHECK(static_cast<int>(bc.size(0)) == O, "bias must have out_channels elements");
    }

    const int OH = static_cast<int>((H + 2 * padding - dilation * (K - 1) - 1) / stride + 1);
    const int OW = static_cast<int>((W + 2 * padding - dilation * (K - 1) - 1) / stride + 1);
    TORCH_CHECK(OH > 0 && OW > 0, "invalid output size");

    auto y = torch::empty({N, O, OH, OW}, xc.options());
    if (N == 0 || O == 0) {
        return y;
    }

    const int co_tiles = (O + CO_BLOCK - 1) / CO_BLOCK;
    dim3 block(TX, TY, 1);
    dim3 grid((OW + TX - 1) / TX, (OH + TY - 1) / TY, N * co_tiles);
    const int IH_TILE = (TY - 1) * static_cast<int>(stride) + (K - 1) * static_cast<int>(dilation) + 1;
    const int IW_TILE = (TX - 1) * static_cast<int>(stride) + (K - 1) * static_cast<int>(dilation) + 1;
    const size_t shmem = static_cast<size_t>(C_TILE) * IH_TILE * IW_TILE * sizeof(float)
                       + static_cast<size_t>(CO_BLOCK) * C_TILE * K * K * sizeof(float);
    if (shmem > 48 * 1024) {
        cudaFuncSetAttribute(
            conv2d_direct_kernel,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            static_cast<int>(shmem));
    }

    auto stream = at::cuda::getCurrentCUDAStream();
    conv2d_direct_kernel<<<grid, block, shmem, stream.stream()>>>(
        xc.data_ptr<float>(),
        wc.data_ptr<float>(),
        bptr,
        y.data_ptr<float>(),
        N, C, H, W,
        O, K, OH, OW,
        static_cast<int>(stride),
        static_cast<int>(padding),
        static_cast<int>(dilation));

    return y;
}
"""

_conv2d_ext = load_inline(
    name="conv2d_direct_co8_ext",
    cpp_sources=[_cpp_src],
    cuda_sources=[_cuda_src],
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False,
    ):
        super(ModelNew, self).__init__()
        self.conv2d = nn.Conv2d(
            in_channels,
            out_channels,
            (kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _conv2d_ext.conv2d_forward(
            x,
            self.conv2d.weight,
            self.conv2d.bias,
            self.conv2d.stride[0],
            self.conv2d.padding[0],
            self.conv2d.dilation[0],
            self.conv2d.groups,
        )

